import sympy as sp; t = sp.Symbol('t'); v = 3*t**2 - 24*t + 36; x = sp.integrate(v, (t, 0, t)); x_func = lambda val: val**3 - 12*val**2 + 36*val; v_func = lambda val: 3*val**2 - 24*val + 36; assert x_func(1) == 25, 'ㄱ 실패'; roots = sp.solve(v, t); assert len(roots) == 2 and roots == [2, 6], 'ㄴ 속도=0 검증 실패'; dist = abs(x_func(2) - x_func(0)) + abs(x_func(3) - x_func(2)); assert dist == 37, f'ㄷ 거리={dist} 검증 실패'; print('VERIFY_PASS')